const entries = Object.entries(MAP).sort((a,b)=>b[0].length-a[0].length);

function displayText(value){
  let s = String(value == null ? '' : value);
  if(Object.prototype.hasOwnProperty.call(MAP, s)) return MAP[s];
  for(const [oldName,newName] of entries){
    if(s.includes(oldName)) s = s.split(oldName).join(newName);
  }
  return s;
}

if(typeof GROUP_LABELS !== 'undefined'){
  const known = new Set(
    typeof PUBLIC_DATA !== 'undefined'
      ? PUBLIC_DATA.map(r=>String((r&&r.group)||'').trim()).filter(Boolean)
      : []
  );
  for(const [code,label] of entries){
    if(Object.prototype.hasOwnProperty.call(GROUP_LABELS, code) || known.has(code)){
      GROUP_LABELS[code] = label;
    }
  }
}

function relabelRoot(root){
  if(!root) return root;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while(walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(n=>{
    const updated = displayText(n.nodeValue);
    if(updated !== n.nodeValue) n.nodeValue = updated;
  });
  return root;
}

/* Карточки строятся функцией card во всех основных представлениях.
   Оборачиваем только визуальный результат; исходные ключи data-group остаются прежними. */
if(typeof card === 'function'){
  const originalCard = card;
  card = function(r){
    return relabelRoot(originalCard(r));
  };
}

